WOLFSSL_CTX*ctx;
...
ret=wolfSSL_CTX_use_certificate_chain_file(ctx,“./cert-chain.pem”);
if(ret!=SSL_SUCCESS){
//errorloadingcertfile
}
...

wolfssl SSLコンテキストにロードされるCA証明書を含むファイルの名前をフォーマットで指定された形式で指定します。 Example intret=0;
WOLFSSL_CTX*ctx;
...
ret=wolfSSL_CTX_der_load_verify_locations(ctx,“./ca-cert.der”,
SSL_FILETYPE_ASN1);
if(ret!=SSL_SUCCESS){
//errorloadingCAcerts
}
...

wolfssl_new（）を使用して作成されたWolfSSL構造へのポインタ。 Example WOLFSSL_CTX*ctx=wolfSSL_CTX_new(method);
WOLFSSL*ssl=wolfSSL_new(ctx);
(void*)ctx;
...
if(ssl!=NULL){
wolfSSL_SetCertCbCtx(ssl,ctx);
}else{
//Errorcase,theSSLisnotinitializedproperly.
}

wolfssl_ctx構造へのポインタ。 Example WOLFSSL_CTX*ctx=wolfSSL_CTX_new(method);
void*userCtx=NULL;//Assignsomeuserdefinedcontext
...
if(ctx!=NULL){
wolfSSL_SetCertCbCtx(ctx,userCtx);
}else{
//Errorcase,theSSLisnotinitializedproperly.
}

wolfssl_ctx構造へのポインタ、証明書情報を保持します。 Example WOLFSSL_CTX*ctx=WOLFSSL_CTX_new(protocoldef);
constchar*fname;
...
if(wolfSSL_CTX_save_cert_cache(ctx,fname)){
//filewaswritten.
}

wolfssl_ctx構造へのポインタ、証明書情報を保持します。 Example WOLFSSL_CTX*ctx=wolfSSL_CTX_new(protocolmethod);
WOLFSSL*ssl=wolfSSL_new(ctx);
constchar*fname="pathtofile";
...
if(wolfSSL_CTX_restore_cert_cache(ctx,fname)){
//checktoseeiftheexecutionwassuccessful
}

出力バッファのサイズ。 Example WOLFSSL_CTX*ctx=WOLFSSL_CTX_new(protocol);
void*mem;
intsz;
int*used;
...
if(wolfSSL_CTX_memsave_cert_cache(ctx,mem,sz,used)!=SSL_SUCCESS){
//Thefunctionreturnedwithanerror
}

simplesect.para:
BAD_MUTEX_E - ミューテックスロックエラーが発生した場合は返されます。 Example WOLFSSL_CTX*ctx=WOLFSSL_CTX_new(protocol);
...
