見つかる拡張OID。 Example constWOLFSSL_X509*x509;
intlastPos=-1;
intidx;

idx=wolfSSL_X509_get_ext_by_NID(x509,NID_basic_constraints,lastPos);

not nullが複数の拡張子に-2に設定されていない場合は-1が見つかりませんでした。 Example constWOLFSSL_X509*x509;
intc;
intidx=0;
STACK_OF(WOLFSSL_ASN1_OBJECT)*sk;

sk=wolfSSL_X509_get_ext_d2i(x509,NID_basic_constraints,&c,&idx);
//checkskforNULLandthenuseit.skneedsfreedafterdone.

ハッシュを保持するためのバッファ。 Example WOLFSSL_X509*x509;
unsignedcharbuffer[64];
unsignedintbufferSz;
intret;

ret=wolfSSL_X509_digest(x509,wolfSSL_EVP_sha256(),buffer,&bufferSz);
//checkretvalue

引数を設定するためのWolfSSL構造。 Example WOLFSSL*ssl;
WOLFSSL_EVP_PKEY*pkey;
intret;
//createsslobjectandsetupprivatekey
ret=wolfSSL_use_PrivateKey(ssl,pkey);
//checkretvalue

バッファー保持DERキー。 Example WOLFSSL*ssl;
unsignedchar*pkey;
longpkeySz;
intret;
//createsslobjectandsetupprivatekey
ret=wolfSSL_use_PrivateKey_ASN1(1,ssl,pkey,pkeySz);
//checkretvalue

バッファー保持DERキー。 Example WOLFSSL*ssl;
unsignedchar*pkey;
longpkeySz;
intret;
//createsslobjectandsetupRSAprivatekey
ret=wolfSSL_use_RSAPrivateKey_ASN1(ssl,pkey,pkeySz);
//checkretvalue

simplesect.para:
NULL 失敗すると Example WOLFSSL_DH*dh;
WOLFSSL_DSA*dsa;
//setupdsa
dh=wolfSSL_DSA_dup_DH(dsa);

//checkdhisnotnull

parameterdescription.para:
DER証明書バッファを持つwolfssl_bio構造体へのポインタ。 Example WOLFSSL_BIO*bio;
WOLFSSL_X509*x509;
//loadDERintobio
x509=wolfSSL_d2i_X509_bio(bio,NULL);
Or
wolfSSL_d2i_X509_bio(bio,&x509);
//usex509returned(checkforNULL)

パスワードコールバック Example WOLFSSL_BIO*bio;
WOLFSSL_X509*x509;
//setupbio
X509=wolfSSL_PEM_read_bio_X509_AUX(bio,NULL,NULL,NULL);
//checkx509isnotnullandthenuseit

wolfssl_ctx_new（）を使用して作成されたwolfssl_ctx構造へのポインタ。 Example WOLFSSL_CTX*ctx=wolfSSL_CTX_new(protocolmethod);
WOLFSSL_DH*dh;
…
returnwolfSSL_CTX_set_tmp_dh(ctx,dh);

パスワードコールバック関数 Example WOLFSSL_BIO*bio;
WOLFSSL_DSA*dsa;
//setupbio
dsa=wolfSSL_PEM_read_bio_DSAparams(bio,NULL,NULL,NULL);

//checkdsaisnotNULLandthenusedsa

simplesect.para:
NULL ピア証明書がない場合は返されます。 Example WOLFSSL_CTX*ctx=wolfSSL_CTX_new(method);
WOLFSSL*ssl=wolfSSL_new(ctx);
...
wolfSSL_connect(ssl);
STACK_OF(WOLFSSL_X509)*chain=wolfSSL_get_peer_cert_chain(ssl);
ifchain){
//Youhaveapointertothepeercertificatechain
}

cert->altNamesNext->name wolfssl_x509から、AltNameリストからの文字列値である構造が存在する場合に返されます。 Example WOLFSSL_X509x509=(WOLFSSL_X509*)XMALLOC(sizeof(WOLFSSL_X509),NULL,
DYNAMIC_TYPE_X509);
…
intx509NextAltName=wolfSSL_X509_get_next_altname(x509);
if(x509NextAltName==NULL){
//Thereisn’tanotheraltname
}

NULL x509構造がnullの場合、関数はnullを返します。 Example WOLFSSL_X509*x509=(WOLFSSL_X509)XMALLOC(sizeof(WOLFSSL_X509),NULL,
DYNAMIC_TYPE_X509);
…
constWOLFSSL_ASN1_TIME*notAfter=wolfSSL_X509_get_notBefore(x509);
if(notAfter==NULL){
//Thex509objectwasNULL
}
